import React, { useState } from "react";
import { LuCircleCheck } from "react-icons/lu";

import GForm from "../gh-leads/GForm";
import type { GFormField, GFormTemplate } from "../gh-leads/GForm";

export type ApplicationFormProps = {
  /** Field definitions. This array is the whole form. */
  fields: GFormField[];
  /** Sold by Sajra styling for the shared PPM form component. */
  formTemplate: GFormTemplate;
  submitLabel?: string;
  submittingLabel?: string;
  /** Small print under the submit button. */
  note?: string;
  successTitle?: string;
  successText?: string;
  /**
   * Receives the completed values. Throwing here surfaces the message in the
   * form's own error slot, which is how a missing backend gets reported rather
   * than silently swallowed.
   */
  onSubmit: (values: Record<string, unknown>) => Promise<void> | void;
};

/**
 * The rental application form.
 *
 * A thin wrapper around the shared PPM GForm: the fields come from data, GForm
 * renders and validates them, and this adds only the submitted state. Nothing
 * about the form component is forked, so improvements to it reach every form
 * on the site.
 */
export default function ApplicationForm({
  fields,
  formTemplate,
  submitLabel = "Submit Application",
  submittingLabel = "Sending...",
  note,
  successTitle = "Application received",
  successText = "Thank you. A member of the Sold by Sajra team will be in touch about the next steps.",
  onSubmit,
}: ApplicationFormProps) {
  const [submitted, setSubmitted] = useState(false);

  const handleSubmit = async (values: Record<string, unknown>) => {
    await onSubmit(values);
    setSubmitted(true);
  };

  if (submitted) {
    return (
      <div className="kr-apply__success" role="status">
        <span className="kr-apply__success-icon" aria-hidden="true">
          <LuCircleCheck size={38} strokeWidth={1.3} />
        </span>
        <h2 className="kr-apply__success-title">{successTitle}</h2>
        <p className="kr-apply__success-text">{successText}</p>
      </div>
    );
  }

  return (
    <div className="kr-apply__form">
      <GForm
        fields={fields}
        template={formTemplate}
        submitLabel={submitLabel}
        submittingLabel={submittingLabel}
        onSubmit={handleSubmit}
      />
      {note ? <p className="kr-apply__note">{note}</p> : null}
    </div>
  );
}
