import { featuredImage } from "../../modules/property/derive";
import type { Property, PropertyRecord, ResolvedImage } from "../../modules/property/types";

import h1 from "../../../images/sajra/home-1.jpg";
import h2 from "../../../images/sajra/home-2.jpg";
import h3 from "../../../images/sajra/home-3.jpg";
import h4 from "../../../images/sajra/home-4.jpg";
import h5 from "../../../images/sajra/home-5.jpg";
import h6 from "../../../images/sajra/home-6.jpg";

const one = (src: string): ResolvedImage => ({ src, srcSet: `${src} 1400w` });

/** Photograph keys for the bundled sample listings. CMS-created properties carry their own image URLs and never use this map. */
const IMAGES: Record<string, ResolvedImage> = {
  "home-1": one(h1),
  "home-2": one(h2),
  "home-3": one(h3),
  "home-4": one(h4),
  "home-5": one(h5),
  "home-6": one(h6),
};

export function resolveProperty(record: PropertyRecord): Property {
  // CMS photography overrides the sample image even on an existing listing.
  const own = featuredImage(record);
  if (own?.src) {
    return { ...record, image: own.src, imageSrcSet: own.srcSet };
  }
  const image = IMAGES[record.imageKey];

  if (image) {
    return { ...record, image: image.src, imageSrcSet: image.srcSet };
  }

  /* No key, or a key nothing is registered under. Before assuming the property
     has no photograph, ask the property.

     A bundled listing names its photograph by key, because the file is in the
     repository and webpack has to see the import. A property created in the
     CMS carries its own `images`, already uploaded and already URLs — there is
     nothing in this map for it and there never will be.

     Without this fallback such a property rendered a photograph on its card
     (the CMS applies the same rule itself) and a blank space in its hero, its
     gallery strip and its search result. One rule here rather than four
     `withOwnImage` calls dotted around, because the day somebody adds a fifth
     surface it should not be their job to remember. */
  if (record.imageKey && process.env.NODE_ENV !== "production") {
    /* Narrowed to records that NAME a key. A CMS property has no key by
       design, so warning about it would have trained everyone to ignore this
       — which is how the one real broken key gets missed. */
    console.warn(
      `[property] no image registered for key "${record.imageKey}" (${record.slug})`
    );
  }

  return { ...record, image: "", imageSrcSet: undefined };
}

export function resolveProperties(records: PropertyRecord[]): Property[] {
  return records.map(resolveProperty);
}

export default IMAGES;
