import React from "react";

import formTemplate from "../ppm/config/application-form--template";
import { publickey } from "../ppm/config/gforms--publickey";
import { EMAIL, PHONE_DISPLAY } from "../ppm/config/profile--contact";
import ApplicationForm from "../ppm/modules/application/ApplicationForm";
import {
  requiresPublicKey,
  useHandleSubmitForm,
} from "../ppm/modules/gforms/handleSubmitForm";
import type { GFormField } from "../ppm/modules/gh-leads/GForm";
import { CONTACT_TOPICS } from "./content";

const fields: GFormField[] = [
  { name: "fullName", type: "text", label: "Your name", placeholder: "Full name", required: true },
  { name: "email", type: "email", label: "Email", placeholder: "you@example.com", required: true },
  { name: "phone", type: "tel", label: "Phone", placeholder: "(208) 000-0000" },
  {
    name: "reason",
    type: "select",
    label: "I’m interested in",
    placeholder: "Choose one",
    required: true,
    options: CONTACT_TOPICS,
  },
  {
    name: "message",
    type: "textarea",
    label: "Message",
    placeholder: "Tell Sajra a little about what you’re looking for.",
    rows: 5,
    required: true,
  },
];

/**
 * The one public enquiry form. Submissions go through the same handler the
 * CMS Leads screen reads from, so nothing here knows which backend is live.
 * `subject` is stamped on the front of the message (e.g. a listing's name).
 */
export function useEnquirySubmit(subject?: string) {
  const { handleSubmitForm } = useHandleSubmitForm();

  /** Throws a message fit to show a visitor when the enquiry did not go through. */
  return async (values: Record<string, unknown>) => {
    if (requiresPublicKey() && (!publickey || !publickey.trim())) {
      throw new Error(
        `This form is not connected yet. Please call ${PHONE_DISPLAY} or email ${EMAIL} and Sajra will pick it up from there.`
      );
    }
    const outcome = await handleSubmitForm(values, publickey, undefined, {
      kind: "enquiry",
      ...(subject ? { name: subject } : {}),
    });
    if (outcome && outcome.success === false) {
      throw new Error(`Your message could not be sent. Please try again, or call ${PHONE_DISPLAY}.`);
    }
  };
}

export default function InquiryForm({ subject }: { subject?: string }) {
  const onSubmit = useEnquirySubmit(subject);

  return (
    <ApplicationForm
      fields={fields}
      formTemplate={formTemplate}
      submitLabel="Send message"
      submittingLabel="Sending…"
      note="Your details are only used to reply to this enquiry."
      successTitle="Message sent"
      successText="Thank you. Sajra will be in touch shortly."
      onSubmit={onSubmit}
    />
  );
}
