import { useCallback } from "react";

import { GOOGLE_FORM_ENTITIES } from "../../config/gforms--entry-ids";
import { GOOGLE_FORM_ID } from "../../config/gforms--form-id";
import { GFORMS_SITE_ID } from "../../config/gforms--site-id";


import { buildSubmission } from "./buildSubmission";
import type { SubmissionForm } from "./buildSubmission";
import { generateDummyUser } from "../../utilities/pseudo-data/pseudoUser";
import { useGoogleFormSubmit } from "./useGoogleFormSubmit";
import { encrypt, MAX_CHUNK_SIZE } from "../../utilities/crypto/crypt";
import { submitLead } from "../supabase/leads";
import { usingSupabase } from "../supabase/enabled";

const CURRENT_FORM_VERSION_ID = 0;

const GOOGLE_FORM: any = {
    ...GOOGLE_FORM_ID,
    ...GOOGLE_FORM_ENTITIES,
};

/**
 * Whether a form needs the site's RSA public key before it may submit.
 *
 * The Google Forms transport encrypts every answer in the browser, so without
 * a key there is nothing to send and the form correctly refuses. Supabase has
 * no such requirement — the row is protected by Row Level Security instead —
 * so asking for a key there would block a working form over a value it does
 * not use.
 *
 * Exported because the two public forms check it before they call in, and
 * getting that wrong in either direction is visible to a real applicant.
 */
export const requiresPublicKey = (): boolean => !usingSupabase();

/**
 * What a submit attempt reports back.
 *
 * `success: false` is a real failure and the caller must treat it as one. This
 * matters more with Supabase than it did before: the Google transport posts
 * with `mode: "no-cors"` and genuinely cannot see whether the submission
 * landed, so it optimistically reports success for anything that does not
 * throw. Supabase returns a status code, so a failure here is known rather
 * than assumed — and showing somebody "Application received" over it would be
 * a lie the site is now capable of avoiding.
 */
export type SubmitOutcome = {
    success: boolean;
    error?: unknown;
};

export const useHandleSubmitForm = () => {
    const { submit } = useGoogleFormSubmit({
        form: GOOGLE_FORM,
    });

    /**
     * `form` is optional and additive: the contact form calls this with three
     * arguments exactly as before, and the application form names which
     * application was filled in so the CMS can show it against the submission.
     */
    const handleSubmitForm = useCallback(
        async (
            data: any,
            publicKey: any,
            handleUI?: () => void,
            form?: SubmissionForm
        ): Promise<SubmitOutcome> => {
            /* Every answer is carried, and name/phone/email are resolved from
               whatever the form calls them. This used to name three fields
               directly, so any question an editor added was silently dropped
               between the applicant pressing Submit and the record being
               written. See buildSubmission. */
            const finalPayload = buildSubmission(data ?? {}, {
                submissionId: crypto.randomUUID(),
                siteId: GFORMS_SITE_ID,
                form,
            });

            if (usingSupabase()) {
                /* Straight into the leads table. No encryption step, because
                   there is no untrusted intermediary to hide the answers from
                   — the row is unreadable to anyone who is not signed in. The
                   public key argument is accepted and unused. */
                const result = await submitLead(finalPayload);

                if (!result.ok) {
                    return { success: false, error: result.error.message };
                }

                if (handleUI) {
                    handleUI();
                }

                return { success: true };
            }

            const dummy = generateDummyUser();

            const encrypted = await encrypt(
                JSON.stringify(finalPayload),
                publicKey,
                MAX_CHUNK_SIZE
            );

            const response = await submit({
                [GOOGLE_FORM.dummyName]: dummy.name,
                [GOOGLE_FORM.dummyEmail]: dummy.email,
                [GOOGLE_FORM.dummyFormId]: `${CURRENT_FORM_VERSION_ID}`,
                [GOOGLE_FORM.encryptedCode]: encrypted,
            });

            if (handleUI) {
                handleUI();
            }

            return response;
        },
        [submit]
    );

    return {
        handleSubmitForm,
    };
};
